class Solution {
  public List<String> validateCoupons(String[] code, String[] businessLine, boolean[] isActive) {
    List<String> lines = Arrays.asList("electronics", "grocery", "pharmacy", "restaurant");
    List<int[]> valid = new ArrayList<>();
    for (int i = 0; i < code.length; i++) {
      if (isActive[i] && lines.contains(businessLine[i]) && wellFormed(code[i])) {
        valid.add(new int[] {lines.indexOf(businessLine[i]), i});
      }
    }
    valid.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : code[a[1]].compareTo(code[b[1]]));
    List<String> ans = new ArrayList<>();
    for (int[] v : valid) ans.add(code[v[1]]);
    return ans;
  }

  private boolean wellFormed(String s) {
    if (s.isEmpty()) return false;
    for (char c : s.toCharArray()) {
      if (!Character.isLetterOrDigit(c) && c != '_') return false;
    }
    return true;
  }
}
